import{_ as d,a0 as n,w as a,s as p,I as s,x as t,a1 as i,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"怎麼在 Linux 中運行 DOS 程序 | LCTT x X-CMD","titleTemplate":false,"description":"怎麼在 Linux 中運行 DOS 程序 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎麼在 Linux 中運行 DOS 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎麼在 Linux 中運行 DOS 程序 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171019 How to run DOS programs in Linux","title":"怎麼在 Linux 中運行 DOS 程序","tag":"201710","desc":""},"relativePath":"201710/20171019 How to run DOS programs in Linux.md","filePath":"[post].md"}'),u={name:"201710/20171019 How to run DOS programs in Linux.md"};function g(m,e,f,D,S,O){const l=n("Link");return a(),p("div",null,[e[34]||(e[34]=s("h1",{id:"怎麼在-linux-中運行-dos-程序",tabindex:"-1"},[t("怎麼在 Linux 中運行 DOS 程序 "),s("a",{class:"header-anchor",href:"#怎麼在-linux-中運行-dos-程序","aria-label":"Permalink to “怎麼在 Linux 中運行 DOS 程序”"},"​")],-1)),e[35]||(e[35]=s("blockquote",null,[s("p",null,"QEMU 和 FreeDOS 使得很容易在 Linux 中運行老的 DOS 程序")],-1)),e[36]||(e[36]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/code_computer_development_programming.png?itok=4OM29-82",alt:"How to run DOS programs in Linux",title:"How to run DOS programs in Linux"})],-1)),e[37]||(e[37]=s("p",null,"Image by : opensource.com",-1)),e[38]||(e[38]=s("p",null,"傳統的 DOS 操作系統支持的許多非常優秀的應用程序： 文字處理，電子表格，遊戲和其它的程序。但是一個應用程序太老了，並不意味着它沒用了。",-1)),s("p",null,[e[1]||(e[1]=t("如今有很多理由去運行一箇舊的 DOS 應用程序。或許是從一個遺留的業務應用程序中提取一個報告，或者是想玩一個經典的 DOS 遊戲，或者只是因為你對“傳統計算機”很好奇。你不需要去雙引導你的系統去運行 DOS 程序。取而代之的是，你可以在 Linux 中在一個 PC 仿真程序和 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[0]||(e[0]=[t("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=t(" 的幫助下去正確地運行它們。",-1))]),e[39]||(e[39]=s("p",null,"FreeDOS 是一個完整的、免費的、DOS 兼容的操作系統，你可以用它來玩經典的遊戲、運行舊式業務軟件，或者開發嵌入式系統。任何工作在 MS-DOS 中的程序也可以運行在 FreeDOS 中。",-1)),s("p",null,[e[4]||(e[4]=t("在那些“過去的時光”裏，你安裝的 DOS 是作為一台計算機上的獨佔操作系統。 而現今，它可以很容易地安裝到 Linux 上運行的一台虛擬機中。 ",-1)),i(l,{href:"https://www.qemu.org/"},{default:o(()=>[...e[3]||(e[3]=[t("QEMU",-1)])]),_:1}),e[5]||(e[5]=t(" （",-1)),e[6]||(e[6]=s("ruby",null,[t("快速仿真程序"),s("rt",null,"Quick EMUlator")],-1)),e[7]||(e[7]=t("的縮寫） 是一個開源的虛擬機軟件，它可以在 Linux 中以一個“",-1)),e[8]||(e[8]=s("ruby",null,[t("訪客"),s("rt",null,"guest")],-1)),e[9]||(e[9]=t("”操作系統來運行 DOS。許多流行的 Linux 系統都默認包含了 QEMU 。",-1))]),e[40]||(e[40]=r('<p>通過以下四步，很容易地在 Linux 下通過使用 QEMU 和 FreeDOS 去運行一個老的 DOS 程序。</p><h3 id="第-1-步-設置一個虛擬磁盤" tabindex="-1">第 1 步：設置一個虛擬磁盤 <a class="header-anchor" href="#第-1-步-設置一個虛擬磁盤" aria-label="Permalink to “第 1 步：設置一個虛擬磁盤”">​</a></h3><p>你需要一個地方來在 QEMU 中安裝 FreeDOS，為此你需要一個虛擬的 C: 驅動器。在 DOS 中，字母<code>A:</code> 和 <code>B:</code> 是分配給第一和第二個軟盤驅動器的，而 <code>C:</code> 是第一個硬盤驅動器。其它介質，包括其它硬盤驅動器和 CD-ROM 驅動器，依次分配 <code>D:</code>、<code>E:</code> 等等。</p><p>在 QEMU 中，虛擬磁盤是一個鏡像文件。要初始化一個用做虛擬 <code>C: </code> 驅動器的文件，使用 <code>qemu-img</code> 命令。要創建一個大約 200 MB 的鏡像文件，可以這樣輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-img create dos.img 200M</span></span></code></pre></div><p>與現代計算機相比， 200MB 看起來非常小，但是早在 1990 年代， 200MB 是非常大的。它足夠安裝和運行 DOS。</p><h3 id="第-2-步-qemu-選項" tabindex="-1">第 2 步： QEMU 選項 <a class="header-anchor" href="#第-2-步-qemu-選項" aria-label="Permalink to “第 2 步： QEMU 選項”">​</a></h3><p>與 PC 仿真系統 VMware 或 VirtualBox 不同，你需要通過 QEMU 命令去增加每個虛擬機的組件來 “構建” 你的虛擬系統 。雖然，這可能看起來很費力，但它實際並不困難。這些是我們在 QEMU 中用於去引導 FreeDOS 的參數：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><code>qemu-system-i386</code></td><td style="text-align:left;">QEMU 可以仿真幾種不同的系統，但是要引導到 DOS，我們需要有一個 Intel 兼容的 CPU。 為此，使用 i386 命令啓動 QEMU。</td></tr><tr><td style="text-align:left;"><code>-m 16</code></td><td style="text-align:left;">我喜歡定義一個使用 16MB 內存的虛擬機。它看起來很小，但是 DOS 工作不需要很多的內存。在 DOS 時代，計算機使用 16MB 或者 8MB 內存是非常普遍的。</td></tr><tr><td style="text-align:left;"><code>-k en-us</code></td><td style="text-align:left;">從技術上説，這個 <code>-k</code> 選項是不需要的，因為 QEMU 會設置虛擬鍵盤去匹配你的真實鍵盤（在我的例子中， 它是標準的 US 佈局的英語鍵盤）。但是我還是喜歡去指定它。</td></tr><tr><td style="text-align:left;"><code>-rtc base=localtime</code></td><td style="text-align:left;">每個傳統的 PC 設備有一個實時時鐘 (RTC) 以便於系統可以保持跟蹤時間。我發現它是設置虛擬 RTC 匹配你的本地時間的最簡單的方法。</td></tr><tr><td style="text-align:left;"><code>-soundhw sb16,adlib,pcspk</code></td><td style="text-align:left;">如果你需要聲音，尤其是為了玩遊戲時，我更喜歡定義 QEMU 支持 SoundBlaster 16 聲音硬件和 AdLib 音樂。SoundBlaster 16 和 AdLib 是在 DOS 時代非常常見的聲音硬件。一些老的程序也許使用 PC 喇叭發聲； QEMU 也可以仿真這個。</td></tr><tr><td style="text-align:left;"><code>-device cirrus-vga</code></td><td style="text-align:left;">要使用圖像，我喜歡去仿真一個簡單的 VGA 視頻卡。Cirrus VGA 卡是那時比較常見的圖形卡, QEMU 可以仿真它。</td></tr><tr><td style="text-align:left;"><code>-display gtk</code></td><td style="text-align:left;">對於虛擬顯示，我設置 QEMU 去使用 GTK toolkit，它可以將虛擬系統放到它自己的窗口內，並且提供一個簡單的菜單去控制虛擬機。</td></tr><tr><td style="text-align:left;"><code>-boot order=</code></td><td style="text-align:left;">你可以告訴 QEMU 從多個引導源來引導虛擬機。從軟盤驅動器引導（在 DOS 機器中一般情況下是 <code>A:</code> ）指定 <code>order=a</code>。 從第一個硬盤驅動器引導（一般稱為 <code>C:</code>） 使用 <code>order=c</code>。 或者去從一個 CD-ROM 驅動器（在 DOS 中經常分配為 <code>D:</code> ） 使用 <code>order=d</code>。 你可以使用組合字母去指定一個特定的引導順序， 比如 <code>order=dc</code> 去第一個使用 CD-ROM 驅動器，如果 CD-ROM 驅動器中沒有引導介質，然後使用硬盤驅動器。</td></tr></tbody></table></div><h3 id="第-3-步-引導和安裝-freedos" tabindex="-1">第 3 步： 引導和安裝 FreeDOS <a class="header-anchor" href="#第-3-步-引導和安裝-freedos" aria-label="Permalink to “第 3 步： 引導和安裝 FreeDOS”">​</a></h3><p>現在 QEMU 已經設置好運行虛擬機，我們需要一個 DOS 系統來在那台虛擬機中安裝和引導。 FreeDOS 做這個很容易。它的最新版本是 FreeDOS 1.2， 發行於 2016 年 12 月。</p>',11)),s("p",null,[e[11]||(e[11]=t("從 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[10]||(e[10]=[t("FreeDOS 網站",-1)])]),_:1}),e[12]||(e[12]=t("上下載 FreeDOS 1.2 的發行版。 FreeDOS 1.2 CD-ROM “standard” 安裝器 （",-1)),e[13]||(e[13]=s("code",null,"FD12CD.iso",-1)),e[14]||(e[14]=t("） 可以很好地在 QEMU 上運行，因此，我推薦使用這個版本。",-1))]),e[41]||(e[41]=r('<p>安裝 FreeDOS 很簡單。首先，告訴 QEMU 使用 CD-ROM 鏡像並從其引導。 記住，第一個硬盤驅動器是 <code>C:</code> 驅動器，因此， CD-ROM 將以 <code>D:</code> 驅動器出現。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -display gtk -hda dos.img -cdrom FD12CD.iso -boot order=d</span></span></code></pre></div><p>正如下面的提示，你將在幾分鐘內安裝完成 FreeDOS 。</p><p><img src="https://opensource.com/sites/default/files/u128651/install1a.png" alt="Starting FreeDOS installation" title="Starting FreeDOS installation"></p><p><img src="https://opensource.com/sites/default/files/u128651/install2_0.png" alt="Select your keyboard layout" title="Select your keyboard layout"></p><p><img src="https://opensource.com/sites/default/files/u128651/install3.png" alt="Selecting which packages to install" title="Selecting which packages to install"></p><p><img src="https://opensource.com/sites/default/files/u128651/install4.png" alt="Rebooting after installation" title="Rebooting after installation"></p><p>在你安裝完成之後，關閉窗口退出 QEMU。</p><h3 id="第-4-步-安裝並運行你的-dos-應用程序" tabindex="-1">第 4 步：安裝並運行你的 DOS 應用程序 <a class="header-anchor" href="#第-4-步-安裝並運行你的-dos-應用程序" aria-label="Permalink to “第 4 步：安裝並運行你的 DOS 應用程序”">​</a></h3>',9)),s("p",null,[e[16]||(e[16]=t("一旦安裝完 FreeDOS，你可以在 QEMU 中運行各種 DOS 應用程序。你可以在線上通過各種檔案文件或其它",-1)),i(l,{href:"http://www.freedos.org/links/"},{default:o(()=>[...e[15]||(e[15]=[t("網站",-1)])]),_:1}),e[17]||(e[17]=t("找到老的 DOS 程序。",-1))]),e[42]||(e[42]=r('<p>QEMU 提供了一個在 Linux 上訪問本地文件的簡單方法。比如説，想去用 QEMU 共享 <code>dosfiles/</code> 文件夾。 通過使用 <code>-drive</code> 選項，簡單地告訴 QEMU 去使用這個文件夾作為虛擬的 FAT 驅動器。 QEMU 將像一個硬盤驅動器一樣訪問這個文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-drive file=fat:rw:dosfiles/</span></span></code></pre></div><p>現在，你可以使用合適的選項去啓動 QEMU，加上一個外部的虛擬 FAT 驅動器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -display gtk -hda dos.img -drive file=fat:rw:dosfiles/ -boot order=c</span></span></code></pre></div><p>一旦你引導進入 FreeDOS，你保存在 <code>D:</code> 驅動器中的任何文件將被保存到 Linux 上的 <code>dosfiles/</code> 文件夾中。可以從 Linux 上很容易地直接去讀取該文件；然而，必須注意的是，啓動 QEMU 後，不能從 Linux 中去改變 <code>dosfiles/</code> 這個文件夾。 當你啓動 QEMU 時，QEMU 一次性構建一個虛擬的 FAT 表，如果你在啓動 QEMU 之後，在 <code>dosfiles/</code> 文件夾中增加或刪除文件，仿真程序可能會很困惑。</p><p>我使用 QEMU 像這樣運行一些我收藏的 DOS 程序， 比如 As-Easy-As 電子表格程序。這是一個在上世紀八九十年代非常流行的電子表格程序，它和現在的 Microsoft Excel 和 LibreOffice Calc 或和以前更昂貴的 Lotus 1-2-3 電子表格程序完成的工作是一樣的。 As-Easy-As 和 Lotus 1-2-3 都保存數據為 WKS 文件，最新版本的 Microsoft Excel 不能讀取它，但是，根據兼容性， LibreOffice Calc 可以支持它。</p><p><img src="https://opensource.com/sites/default/files/u128651/aseasy-regress1.png" alt="As-Easy-As spreadsheet program" title="As-Easy-As spreadsheet program"></p><p><em>As-Easy-As 電子表格程序</em></p><p>我也喜歡在 QEMU中引導 FreeDOS 去玩一些收藏的 DOS 遊戲，比如原版的 Doom。這些老的 DOS 遊戲玩起來仍然非常有趣， 並且它們現在在 QEMU 上運行的非常好。</p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-doom.png" alt="Doom" title="Doom"></p><p><em>Doom</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-heretic.png" alt="Heretic" title="Heretic"></p><p><em>Heretic</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-jill.png" alt="Jill of the Jungle" title="Jill of the Jungle"></p><p><em>Jill of the Jungle</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-keen.png" alt="Commander Keen" title="Commander Keen"></p><p><em>Commander Keen</em></p><p>QEMU 和 FreeDOS 使得在 Linux 上運行老的 DOS 程序變得很容易。你一旦設置好了 QEMU 作為虛擬機仿真程序並安裝了 FreeDOS，你將可以在 Linux 上運行你收藏的經典的 DOS 程序。</p>',18)),s("p",null,[s("em",null,[e[19]||(e[19]=t("所有圖片要致謝 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[18]||(e[18]=[t("FreeDOS.org",-1)])]),_:1}),e[20]||(e[20]=t("。",-1))])]),e[43]||(e[43]=s("hr",null,null,-1)),e[44]||(e[44]=s("p",null,"作者簡介：",-1)),e[45]||(e[45]=s("p",null,"Jim Hall 是一位開源軟件的開發者和支持者，可能最廣為人知的是他是 FreeDOS 的創始人和項目協調者。 Jim 也非常活躍於開源軟件適用性領域，作為 GNOME Outreachy 適用性測試的導師，同時也作為一名兼職教授，教授一些開源軟件適用性的課程，從 2016 到 2017， Jim 在 GNOME 基金會的董事會擔任董事，在工作中， Jim 是本地政府部門的 CIO。",-1)),e[46]||(e[46]=s("hr",null,null,-1)),s("p",null,[e[22]||(e[22]=t("via: ",-1)),i(l,{href:"https://opensource.com/article/17/10/run-dos-applications-linux"},{default:o(()=>[...e[21]||(e[21]=[t("https://opensource.com/article/17/10/run-dos-applications-linux",-1)])]),_:1})]),s("p",null,[e[26]||(e[26]=t("作者：",-1)),i(l,{href:"https://opensource.com/users/jim-hall"},{default:o(()=>[...e[23]||(e[23]=[t("Jim Hall",-1)])]),_:1}),e[27]||(e[27]=t(" 譯者：",-1)),i(l,{href:"https://github.com/qhwdw"},{default:o(()=>[...e[24]||(e[24]=[t("qhwdw",-1)])]),_:1}),e[28]||(e[28]=t(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:o(()=>[...e[25]||(e[25]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[31]||(e[31]=t("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[29]||(e[29]=[t("LCTT",-1)])]),_:1}),e[32]||(e[32]=t(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:o(()=>[...e[30]||(e[30]=[t("Linux中國",-1)])]),_:1}),e[33]||(e[33]=t(" 榮譽推出",-1))])])}const M=d(u,[["render",g]]);export{k as __pageData,M as default};
